/** Real app-role PG, real accounting approval/posting and source authorization. Identity eligibility alone is stubbed. */
class FinanceInsightActionIntegrationTest {
 static EmbeddedPostgres pg;static JdbcTemplate jdbc;static NamedParameterJdbcTemplate named;static TransactionTemplate tx;
 static FinanceAccountingService accounting;static FinanceLedgerGovernance governance;static FinanceInsightService insights;static FinanceInsightActionService actions;static EffectiveIdentityService identities;
 static final UUID T=UUID.fromString("10000000-0000-0000-0000-000000000001");UUID hotel,company,book,author,assigner,owner,verifier,outsider,report,voucher;
 @BeforeAll static void start()throws Exception{pg=EmbeddedPostgres.builder().start();var ds=pg.getPostgresDatabase();jdbc=new JdbcTemplate(ds);jdbc.execute("create role hotel_ai_os_app nologin nosuperuser nobypassrls");Flyway.configure().dataSource(ds).locations("classpath:db/migration").target("105").load().migrate();named=new NamedParameterJdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);tx=new TransactionTemplate(manager);var db=new TenantDatabaseContext(jdbc,true);var access=new AccessPolicy();var audit=new AuditWriter(named,e->{});accounting=new FinanceAccountingService(named,db,access,audit,JSON);governance=new FinanceLedgerGovernance(named,db,access,accounting);insights=new FinanceInsightService(named,db,access,audit,accounting,new FinanceAnalysisGateway("","","",false),manager);var sources=new FinanceArchiveSources(named,access,null,null,accounting,null,insights,null);identities=mock(EffectiveIdentityService.class);actions=new FinanceInsightActionService(named,db,access,audit,insights,sources,identities);}
 @AfterAll static void stop()throws Exception{if(pg!=null)pg.close();}
 @AfterEach void clear(){TenantContext.clear();}
 @BeforeEach void seed(){reset(identities);hotel=UUID.randomUUID();company=UUID.randomUUID();book=UUID.randomUUID();report=UUID.randomUUID();author=account();assigner=account();owner=account();verifier=account();outsider=account();jdbc.update("insert into org_unit(id,tenant_id,code,name,unit_type) values(?,?,?,'建议闭环验收门店','HOTEL')",hotel,T,hotel.toString());jdbc.update("insert into finance_company(id,tenant_id,name,tax_number) values(?,?,'建议闭环法人',?)",company,T,company.toString().replace("-",""));jdbc.update("insert into finance_store_config(tenant_id,hotel_id,company_id,manager_account_id,finance_account_id,director_account_id,leader_account_id,cashier_account_id,workflow_version,enabled) values(?,?,?,?,?,?,?,?,2,true)",T,hotel,company,assigner,verifier,account(),account(),verifier);
  when(identities.inspectNotificationRecipient(eq(T),any(UUID.class),nullable(UUID.class))).thenAnswer(invocation->{UUID actor=invocation.getArgument(1);return Optional.of(principal(actor,Set.of(hotel),actor.equals(verifier)?Set.of("finance.review","finance.accounting.read"):Set.of("finance.submit","finance.accounting.read")));});as(author,"*");call(()->accounting.createBook(new FinanceAccountingModels.Book(book,hotel,company,"真实核实账套",LocalDate.of(2026,10,1))));account("1122","ASSET","DEBIT");account("4001","EQUITY","CREDIT");voucher=postedVoucher();
  UUID snapshot=UUID.randomUUID();String sourceVersion=FinanceService.hash(report.toString());var frozen=Map.of("scope",List.of(hotel),"books",List.of(Map.of("bookId",book,"hotelId",hotel,"hotelName","建议闭环验收门店","companyId",company,"reportVersion",sourceVersion)),"facts",List.of(Map.of("id","REVENUE","value","100.00","complete",true)),"reportVersion",sourceVersion,"month","2026-10");
  // Fixed analysis fixture only; publication still passes the production independent review gate. No model/external data is sent.
  jdbc.update("insert into fi_snapshot(id,tenant_id,month,hotel_ids,report_version,facts,created_by) values(?,?,'2026-10-01',?::uuid[],?,?::jsonb,?)",snapshot,T,"{"+hotel+"}",sourceVersion,json(frozen),author);jdbc.update("insert into fi_report(id,tenant_id,snapshot_id,title,created_by,last_edited_by,model,model_request_hash) values(?,?,?,'事实引用建议',?,?,'isolated-fixture',?)",report,T,snapshot,author,author,sourceVersion);jdbc.update("insert into fi_report_revision(tenant_id,report_id,version,content,edited_by) values(?,?,0,?::jsonb,?)",T,report,json(Map.of("analysis",List.of(),"recommendations",List.of(Map.of("text","核对真实应收并补齐来源","citations",List.of("REVENUE"),"uncertainty","需人工核实结果")))),author);as(assigner,"*");call(()->insights.transition(report,0,false));call(()->insights.transition(report,0,true));call(()->insights.followup(report,new FinanceInsightModels.Recommendation(UUID.randomUUID(),-1,0,"ADOPTED",owner,LocalDate.of(2026,10,1),"明确采纳，要求真实依据和独立核实")));}
 @Test void actualOwnerCanWorkWithoutBroadReviewButManagersCannotActForOtherOwners(){UUID task=assign();as(owner,"finance.submit","finance.accounting.read");var detail=call(()->actions.detail(task));assertThat(detail).containsEntry("canWork",true).containsEntry("canReview",false);assertThat(rows(call(()->actions.list(0)).get("items"))).anySatisfy(r->assertThat(r).containsEntry("id",task));as(outsider,"finance.review","finance.configure");assertThat(call(()->actions.detail(task))).containsEntry("canWork",false);assertThatThrownBy(()->call(()->actions.start(task,new FinanceInsightActionModels.Move(UUID.randomUUID(),0,"不能以配置权代做")))).isInstanceOf(AccessDeniedException.class);as(owner,"finance.submit");call(()->actions.start(task,new FinanceInsightActionModels.Move(UUID.randomUUID(),0,"本人先核对原始业务")));assertThatThrownBy(()->call(()->actions.preview(task,"VOUCHER",voucher))).isInstanceOf(AccessDeniedException.class);assertThat(jdbc.queryForObject("select count(*) from fi_action_update where task_id=?",Integer.class,task)).isEqualTo(2);}
 @Test void completionRequiresRealPostedSourceAndDesignatedIndependentVerifierWithCurrentSourcePrivilege(){UUID task=assign();as(owner,"finance.submit","finance.accounting.read");var preview=call(()->actions.preview(task,"VOUCHER",voucher));var input=new FinanceInsightActionModels.Submit(UUID.randomUUID(),0,"已按原建议处理真实来源，待独立核实",List.of(new FinanceInsightActionModels.Proof("VOUCHER",voucher,preview.get("sourceVersion").toString())));var submitted=call(()->actions.submit(task,input));assertThat(submitted).containsEntry("status","SUBMITTED");assertThat(call(()->actions.submit(task,input))).containsEntry("version",1);as(owner,"*");assertThatThrownBy(()->call(()->actions.review(task,new FinanceInsightActionModels.Review(UUID.randomUUID(),1,true,"本人不能自证")))).isInstanceOf(AccessDeniedException.class);as(outsider,"*");assertThatThrownBy(()->call(()->actions.review(task,new FinanceInsightActionModels.Review(UUID.randomUUID(),1,true,"其他广泛审核人也不能代替指定人")))).isInstanceOf(AccessDeniedException.class);as(verifier,"finance.review");assertThatThrownBy(()->call(()->actions.review(task,new FinanceInsightActionModels.Review(UUID.randomUUID(),1,true,"缺少原来源读取权限")))).isInstanceOf(AccessDeniedException.class);as(verifier,"finance.review","finance.accounting.read");var approve=new FinanceInsightActionModels.Review(UUID.randomUUID(),1,true,"已在原账簿核实凭证、原始业务版本及应收结果，结论通过");var done=call(()->actions.review(task,approve));assertThat(done).containsEntry("status","DONE").containsEntry("reviewedBy",verifier).containsEntry("submittedBy",owner);assertThat(call(()->actions.review(task,approve))).containsEntry("version",2);assertThat(jdbc.queryForObject("select count(*) from fi_action_evidence where task_id=?",Integer.class,task)).isOne();assertThatThrownBy(()->jdbc.update("update fi_action_evidence set source_hash=? where task_id=?","0".repeat(64),task)).hasMessageContaining("append-only");assertThatThrownBy(()->jdbc.update("update fi_action_update set note='覆盖依据' where task_id=?",task)).hasMessageContaining("append-only");assertThat(jdbc.queryForObject("select count(*) from notification where source_type='FINANCE_INSIGHT_ACTION' and source_id=?",Integer.class,task)).isEqualTo(3);}
 @Test void draftOrChangedAndReversedEvidenceCannotBeRubberStampedAndReworkKeepsPriorProof(){UUID task=assign();as(author,"*");UUID draft=UUID.randomUUID();call(()->accounting.createVoucher(new FinanceAccountingModels.Voucher(draft,book,LocalDate.of(2026,10,13),LocalDate.of(2026,10,13),"未审核业务",lines())));as(owner,"finance.submit","finance.accounting.read");assertThatThrownBy(()->call(()->actions.preview(task,"VOUCHER",draft))).hasMessageContaining("尚未完成");var proof=call(()->actions.preview(task,"VOUCHER",voucher));call(()->actions.submit(task,new FinanceInsightActionModels.Submit(UUID.randomUUID(),0,"待核实真实过账",List.of(new FinanceInsightActionModels.Proof("VOUCHER",voucher,proof.get("sourceVersion").toString())))));as(assigner,"*");call(()->accounting.reverse(voucher,new FinanceAccountingModels.Reverse(UUID.randomUUID(),2,LocalDate.of(2026,10,15),"实际发现差错受控红冲")));as(verifier,"finance.review","finance.accounting.read");assertThatThrownBy(()->call(()->actions.review(task,new FinanceInsightActionModels.Review(UUID.randomUUID(),1,true,"旧依据已被红冲，不能通过")))).hasMessageContaining("尚未完成");call(()->actions.review(task,new FinanceInsightActionModels.Review(UUID.randomUUID(),1,false,"原凭证后续发生差错，请补充新来源")));as(owner,"finance.submit","finance.accounting.read");assertThat(call(()->actions.detail(task))).containsEntry("status","REWORK").containsEntry("canWork",true);assertThat(rows(call(()->actions.detail(task)).get("evidence"))).hasSize(1);assertThatThrownBy(()->call(()->actions.submit(task,new FinanceInsightActionModels.Submit(UUID.randomUUID(),2,"纯自报不能闭环",List.of())))).hasMessageContaining("1至20");assertThatThrownBy(()->call(()->actions.preview(task,"INSIGHT",report))).hasMessageContaining("不接受");}
 @Test void scopeTenantEligibilityAndOldFollowupCannotGrantOwnershipOrSelfReportedDone(){UUID task=assign();TenantContext.set(principal(owner,Set.of(UUID.randomUUID()),Set.of("*")));assertThatThrownBy(()->call(()->actions.detail(task))).isInstanceOf(AccessDeniedException.class);Integer hidden=tx.execute(s->{jdbc.execute("set local role hotel_ai_os_app");jdbc.queryForObject("select set_config('app.tenant_id',?,true)",String.class,UUID.randomUUID().toString());return jdbc.queryForObject("select count(*) from fi_action_task",Integer.class);});assertThat(hidden).isZero();as(assigner,"*");assertThatThrownBy(()->call(()->insights.followup(report,new FinanceInsightModels.Recommendation(UUID.randomUUID(),0,0,"DONE",owner,LocalDate.now(),"一段自报不能完成")))).hasMessageContaining("不能直接标记完成");assertThatThrownBy(()->call(()->actions.assign(new FinanceInsightActionModels.Assign(UUID.randomUUID(),report,0,0,hotel,owner,owner,"不允许自审",LocalDate.of(2026,10,1),"不能自审")))).hasMessageContaining("不能是同一");as(assigner,"*");call(()->actions.cancel(task,new FinanceInsightActionModels.Move(UUID.randomUUID(),0,"原分配人说明取消，保留全部历史")));assertThat(jdbc.queryForObject("select status from fi_action_task where id=?",String.class,task)).isEqualTo("CANCELLED");}
 @Test void assignmentEligibilityIsLiveAndRequestReplayCannotChangeOwnerOrDueDate(){when(identities.inspectNotificationRecipient(eq(T),eq(owner),nullable(UUID.class))).thenReturn(Optional.of(principal(owner,Set.of(UUID.randomUUID()),Set.of("finance.submit"))));as(assigner,"*");var input=new FinanceInsightActionModels.Assign(UUID.randomUUID(),report,0,0,hotel,owner,verifier,"真实应收来源跟进",LocalDate.of(2026,10,1),"本人办理与指定独立核实");assertThatThrownBy(()->call(()->actions.assign(input))).hasMessageContaining("责任人当前没有");when(identities.inspectNotificationRecipient(eq(T),eq(owner),nullable(UUID.class))).thenReturn(Optional.of(principal(owner,Set.of(hotel),Set.of("finance.submit"))));assertThat(call(()->actions.assign(input))).containsEntry("id",input.requestId());assertThat(call(()->actions.assign(input))).containsEntry("version",0);assertThatThrownBy(()->call(()->actions.assign(new FinanceInsightActionModels.Assign(input.requestId(),report,0,0,hotel,owner,verifier,input.title(),LocalDate.of(2026,11,1),input.note())))).hasMessageContaining("请求编号已绑定");assertThatThrownBy(()->jdbc.update("update fi_action_task set owner_id=? where id=?",outsider,input.requestId())).hasMessageContaining("immutable");}
 @Test void realConfirmedHoursAndEnergyIntensityUseExactMeasurementRevisionsAndNeverAssumeZeroRoomNights(){as(assigner,"*");metric("WORK_HOURS","40.0000",-1);metric("ENERGY_KWH","200.0000",-1);metric("WATER_TON","10.0000",-1);metric("ROOM_NIGHTS","50.0000",-1);var first=call(()->insights.dashboard("2026-10",hotel));assertThat(amount(measurement(first,"ENERGY_PER_ROOM_NIGHT").get("value"))).isEqualByComparingTo("4.000000");assertThat(amount(measurement(first,"WATER_PER_ROOM_NIGHT").get("value"))).isEqualByComparingTo("0.200000");assertThat(amount(measurement(first,"WORK_HOURS").get("value"))).isEqualByComparingTo("40.0000");assertThat(measurement(first,"REVENUE_PER_WORK_HOUR").get("value")).isNull();assertThat(rows(measurement(first,"ENERGY_PER_ROOM_NIGHT").get("metricSourceVersions"))).hasSize(2);var frozen=call(()->insights.freeze(new FinanceInsightModels.Generate(UUID.randomUUID(),"2026-10",hotel,first.get("reportVersion").toString())));metric("ENERGY_KWH","300.0000",0);var revised=call(()->insights.dashboard("2026-10",hotel));assertThat(amount(measurement(revised,"ENERGY_PER_ROOM_NIGHT").get("value"))).isEqualByComparingTo("6.000000");assertThat(amount(measurement(call(()->insights.snapshot(id(frozen.get("snapshotId")))),"ENERGY_PER_ROOM_NIGHT").get("value"))).isEqualByComparingTo("4.000000");metric("ROOM_NIGHTS","0.0000",0);assertThat(measurement(call(()->insights.dashboard("2026-10",hotel)),"ENERGY_PER_ROOM_NIGHT")).containsEntry("value",null).containsEntry("complete",false);}
 @Test void cancellationAllowsExplicitReassignmentWithoutErasingOriginalAndDoneRequiresNonNullIndependentIdentity(){UUID original=assign();call(()->actions.cancel(original,new FinanceInsightActionModels.Move(UUID.randomUUID(),0,"原分配终止，不擦除历史，另作明确分配")));UUID replacement=assign();assertThat(replacement).isNotEqualTo(original);assertThat(jdbc.queryForObject("select count(*) from fi_action_task where report_id=?",Integer.class,report)).isEqualTo(2);jdbc.update("update fi_action_task set status='SUBMITTED',version=1,submission_version=1,submitted_by=? where id=?",owner,replacement);assertThatThrownBy(()->jdbc.update("update fi_action_task set status='DONE',version=2,reviewed_by=null,reviewed_at=now() where id=?",replacement)).hasMessageContaining("check");assertThat(jdbc.queryForObject("select status from fi_action_task where id=?",String.class,replacement)).isEqualTo("SUBMITTED");}
 @Test void budgetSourceAggregationKeepsInventoryFundingSeparateFromActualConsumptionAndOpenIssuesCannotMeanZeroCost(){as(assigner,"*");UUID department=UUID.randomUUID();jdbc.update("insert into org_unit(id,tenant_id,parent_id,code,name,unit_type) values(?,?,?,?,?,'DEPARTMENT')",department,T,hotel,department.toString(),"真实使用部门");flow("PROCUREMENT","INVENTORY","0.00","50.00","0.00","0.00",department);flow("RECEIPT","INVENTORY","0.00","0.00","0.00","100.00",department);flow("RETURN","INVENTORY","0.00","0.00","0.00","-20.00",department);flow("INVENTORY","EXPENSE","0.00","0.00","30.00","0.00",department);flow("ACCRUAL","EXPENSE","0.00","0.00","10.00","0.00",department);UUID issue=UUID.randomUUID();jdbc.update("insert into fbu_issue(tenant_id,source_kind,source_id,hotel_id,message,status) values(?,'INVENTORY',?,?,'另有真实领用待财务确认部门与类别，不能按零成本','OPEN')",T,issue,hotel);var first=call(()->insights.dashboard("2026-10",hotel));var sources=rows(first.get("budgetBusinessSources"));assertThat(sources.stream().map(r->amount(r.get("actual"))).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo("40.00");assertThat(sources.stream().map(r->amount(r.get("inventoryValue"))).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo("80.00");assertThat(first).containsEntry("budgetSourceCoverage","INCOMPLETE_OPEN_SOURCE_CLASSIFICATION_ISSUES");assertThat(rows(first.get("budgetSourceIssues"))).hasSize(1);assertThat(rows(first.get("facts")).stream().filter(r->r.get("id").toString().startsWith("BUDGET_SOURCE:"))).allSatisfy(r->assertThat(r.get("complete")).isEqualTo(false));var frozen=call(()->insights.freeze(new FinanceInsightModels.Generate(UUID.randomUUID(),"2026-10",hotel,first.get("reportVersion").toString())));jdbc.update("update fbu_issue set status='RESOLVED',updated_at=now() where tenant_id=? and source_id=?",T,issue);var current=call(()->insights.dashboard("2026-10",hotel));assertThat(current).containsEntry("budgetSourceCoverage","REGISTERED_SOURCES_WITHOUT_OPEN_ISSUES");assertThat(current.get("reportVersion")).isNotEqualTo(first.get("reportVersion"));assertThat(call(()->insights.snapshot(id(frozen.get("snapshotId"))))).containsEntry("budgetSourceCoverage","INCOMPLETE_OPEN_SOURCE_CLASSIFICATION_ISSUES");}
 private void flow(String source,String basis,String inflight,String committed,String actual,String inventory,UUID department){UUID id=UUID.randomUUID();jdbc.update("insert into fbu_flow(id,tenant_id,hotel_id,company_id,source_kind,source_id,line_id,document_id,month,category_code,department_id,basis_kind,inflight,committed,actual,inventory_value,source_version,source_hash,snapshot) values(?,?,?,?,?,?,?,?,'2026-10-01','COST-REAL',?,?,?::numeric,?::numeric,?::numeric,?::numeric,0,?,'{}')",id,T,hotel,company,source,UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),department,basis,inflight,committed,actual,inventory,FinanceService.hash(id.toString()));}
 private void metric(String kind,String value,int version){call(()->insights.saveMetric(new FinanceInsightModels.Metric(UUID.randomUUID(),hotel,"2026-10",kind,"",new BigDecimal(value),"隔离验收已核对的实际仪表/工时汇总来源，不代表接入外部自动采集",version)));}
 private Map<String,Object> measurement(Map<String,Object> data,String metric){return rows(data.get("facts")).stream().filter(row->row.get("id").equals(hotel+":"+metric)).findFirst().orElseThrow();}
 private UUID assign(){as(assigner,"*");UUID id=UUID.randomUUID();call(()->actions.assign(new FinanceInsightActionModels.Assign(id,report,0,0,hotel,owner,verifier,"核实真实应收来源与结果",LocalDate.of(2026,10,1),"已采纳建议显式分配；不自动执行资金或绩效")));return id;}
 private UUID postedVoucher(){as(author,"*");UUID id=UUID.randomUUID();call(()->accounting.createVoucher(new FinanceAccountingModels.Voucher(id,book,LocalDate.of(2026,10,12),LocalDate.of(2026,10,12),"真实已验证业务依据",lines())));as(assigner,"*");call(()->accounting.review(id,0));call(()->accounting.post(id,1));return id;}
 private List<FinanceAccountingModels.Line> lines(){return List.of(new FinanceAccountingModels.Line("1122",new BigDecimal("100.00"),BigDecimal.ZERO,"真实应收",null),new FinanceAccountingModels.Line("4001",BigDecimal.ZERO,new BigDecimal("100.00"),"真实权益",null));}
 private void account(String code,String type,String direction){as(author,"*");UUID request=UUID.randomUUID();call(()->governance.account(request,new FinanceAccountingModels.Account(book,code,"核实科目"+code,type,direction,"核实分类",false,true,-1),"真实科目独立发布"));as(assigner,"*");call(()->governance.publish(request,new FinanceControlModels.Version(0,"独立核实科目"),false));}
 private UUID account(){UUID id=UUID.randomUUID();jdbc.update("insert into user_account(id,tenant_id,login_name,display_name) values(?,?,?,'建议跟进验收账号')",id,T,id.toString());return id;}
 private static TenantPrincipal principal(UUID actor,Set<UUID> scopes,Set<String> permissions){return new TenantPrincipal(T,actor,"TEST",Set.of("TEST"),permissions,scopes,Set.of(),false,UUID.randomUUID());}
 private void as(UUID actor,String...permissions){TenantContext.set(principal(actor,Set.of(hotel),Set.of(permissions)));}
 private static <R> R call(Supplier<R> action){return tx.execute(s->{jdbc.execute("set local role hotel_ai_os_app");return action.get();});}
}
